schema=load(REPO/'generate/pipeline/pedagogical-variation.schema.json')
def validate(value,s):
 if '$ref' in s:raise AssertionError('Unexpected schema ref')
 if 'enum' in s:assert value in s['enum']
 t=s.get('type');assert t is None or {'object':isinstance(value,dict),'array':isinstance(value,list),'string':isinstance(value,str),'integer':type(value) is int,'number':isinstance(value,(int,float))}.get(t,False)
 if t=='object':
  assert all(k in value for k in s.get('required',[]))
  if s.get('additionalProperties') is False:assert set(value)<=set(s['properties'])
  for k,v in value.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k])
 if t=='array':
  assert len(value)>=s.get('minItems',0)
  for v in value:validate(v,s['items'])
 if t=='string':assert len(value)>=s.get('minLength',0)
 if t in ('integer','number'):assert value>=s.get('minimum',float('-inf')) and value<=s.get('maximum',float('inf'))
